{
  "probability": 0.58,
  "range_low": 0.50,
  "range_high": 0.66,
  "summary": [
    "- OPCW-confirmed presence of riot-control agent CS on frontlines indicates chemical agents are deployed in Ukraine's combat zones, elevating the probability of future CW use.",
    "- Dutch/German intelligence reports describe Russia increasing and standardizing chemical weapons usage, pushing the posterior higher.",
    "- Attribution remains uncertain, which moderates the push and sustains tail risk, while strong international norms and enforcement under the CWC provide downward pressure.",
    "- Together, these factors yield a calibrated posterior near 58%, with an uncertainty spread reflecting both real-world incidents and attribution challenges."
  ],
  "confidence": "medium",
  "narrative": "A Bayesian update lifts the base rate from around 12% to a near-term posterior of about 58% as OPCW CS detections and credible intelligence suggest elevated use risk, tempered by attribution uncertainty and deterrence effects. The probability remains uncertain and policy-normalized, with a nonzero tail risk into 2026.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Reference-class anchor: near-term forecasts of CW/biological use in the Russia-Ukraine war; central 12% with 1–23% spread."
    },
    "factor_updates": [
      {
        "factor": "OPCW-confirmed presence of riot-control agent CS on frontlines",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Direct CS detections indicate chemical agents are being employed in or near combat contexts, increasing future-use likelihood."
      },
      {
        "factor": "Intelligence reports of Russia increasing use of banned chemical weapons (chloropicrin, CS)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Credible state-level reporting of escalation and normalization of CW use raises the base risk."
      },
      {
        "factor": "Attribution uncertainty around perpetrators",
        "direction": "neutral",
        "magnitude": "moderate",
        "rationale": "CS incidents lack definitive attribution, which tempers certainty but does not negate risk."
      },
      {
        "factor": "International norms and enforcement under the Chemical Weapons Convention",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Deterrence and potential costs may curb use, offsetting some upward pressure."
      }
    ],
    "synthesis_rationale": "Starting from a modest anchor near 0.12, upward updates from operational CS detections and escalation reports dominate but are tempered by attribution gaps and deterrence effects. The combination yields a posterior around 0.58, reflecting nonzero but uncertain risk with potential correlation among factors."
  }
}

